FUNNEL_CSS = '''*{box-sizing:border-box;margin:0;padding:0}
:root{--bg:#03060c;--bg2:#070d1a;--bg3:#0b1426;--ink:#eef4ff;--dim:#93a3bc;--faint:#55627a;--line:rgba(120,170,255,.14);--blue:#2f8bff;--cyan:#4fd0ff;--grad:linear-gradient(120deg,#4fd0ff 0%,#2f8bff 45%,#6a5cff 100%);--display:"Unbounded",system-ui,sans-serif;--sans:"Inter Tight",system-ui,sans-serif;--pad:clamp(16px,4vw,56px)}
html{background:var(--bg)}body{background:var(--bg);color:var(--ink);font:17px/1.6 var(--sans);-webkit-font-smoothing:antialiased;overflow-x:hidden}
a{color:inherit}.wrap{max-width:1160px;margin:0 auto;padding:0 var(--pad)}
.grad{background:var(--grad);-webkit-background-clip:text;background-clip:text;color:transparent}
.eb{font:600 12px/1 var(--sans);letter-spacing:.18em;text-transform:uppercase;color:var(--cyan)}
h1,h2,h3{font-family:var(--display);font-weight:600;line-height:1.08;letter-spacing:-.02em}
h1{font-size:clamp(34px,6.2vw,76px)}h1 span.l{display:block}h2{font-size:clamp(26px,4vw,46px);margin:14px 0 18px}h3{font-size:19px;margin-bottom:8px}
.top{display:flex;justify-content:space-between;align-items:center;padding:18px var(--pad);position:absolute;inset:0 0 auto;z-index:3}
.brand{display:flex;align-items:center;gap:10px}.brand img{height:36px;width:36px}.brand b{font:600 13px/1 var(--display);letter-spacing:.12em}.btn{display:inline-flex;align-items:center;gap:10px;padding:16px 26px;border-radius:999px;background:var(--grad);color:#fff;font-weight:700;text-decoration:none;border:0;cursor:pointer;font-size:16px}
.btn.sm{padding:10px 18px;font-size:14px}.btn.gh{background:transparent;border:1px solid var(--line)}
.hero{position:relative;min-height:100svh;display:flex;align-items:flex-end;padding:120px 0 64px;overflow:hidden}
.hero video,.hero .sh{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}.hero .sh{background:linear-gradient(180deg,rgba(3,6,12,.55),rgba(3,6,12,.75) 55%,var(--bg))}
.hero .wrap{position:relative;z-index:2}.hero p.sub{max-width:640px;color:var(--silver,#c9d4e4);font-size:clamp(17px,2vw,20px);margin:22px 0 30px}
.note{display:block;margin-top:14px;color:var(--dim);font-size:14px}
.stats{display:grid;grid-template-columns:repeat(4,1fr);border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
.stats div{padding:28px 18px;border-right:1px solid var(--line)}.stats div:last-child{border:0}.stats b{display:block;font:600 clamp(24px,3vw,36px)/1.1 var(--display)}.stats span{color:var(--dim);font-size:14px}
section{padding:clamp(64px,9vw,110px) 0}.lead{color:var(--dim);max-width:640px}
.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:34px}.card{background:var(--bg2);border:1px solid var(--line);border-radius:18px;padding:26px}.card p{color:var(--dim);font-size:16px}
.card .n{font:600 13px var(--display);color:var(--cyan);display:block;margin-bottom:14px}
.polls{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin-top:30px}.polls li{list-style:none;background:var(--bg3);border:1px solid var(--line);border-radius:14px;padding:18px 20px;font-weight:600}
.polls li:before{content:"\\201C";color:var(--cyan);font:700 26px/0 var(--display);margin-right:6px;vertical-align:-8px}
.fit{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:30px}.fit ul{list-style:none}.fit li{padding:10px 0 10px 30px;position:relative;border-bottom:1px solid var(--line);color:var(--dim)}
.fit li:before{position:absolute;left:0;font-weight:700}.fit .y li:before{content:"\\2713";color:var(--cyan)}.fit .x li:before{content:"\\2715";color:#ff6b7d}
.founder{display:grid;grid-template-columns:220px 1fr;gap:34px;align-items:center}.founder img{width:100%;border-radius:18px;aspect-ratio:4/5;object-fit:cover}
details{border-bottom:1px solid var(--line);padding:20px 0}summary{cursor:pointer;font-weight:700;font-size:18px;list-style:none;display:flex;justify-content:space-between;gap:16px}summary:after{content:"+";color:var(--cyan)}details[open] summary:after{content:"\\2212"}details p{color:var(--dim);margin-top:12px}
.final{text-align:center;background:radial-gradient(ellipse at center,rgba(47,139,255,.18),transparent 70%)}.final p{margin:0 auto 28px}
footer{padding:30px var(--pad);border-top:1px solid var(--line);color:var(--faint);font-size:13px;display:flex;justify-content:space-between;flex-wrap:wrap;gap:10px}
@media(max-width:820px){.stats{grid-template-columns:1fr 1fr}.stats div:nth-child(2){border-right:0}.stats div:nth-child(-n+2){border-bottom:1px solid var(--line)}.cards,.polls,.fit{grid-template-columns:1fr}.founder{grid-template-columns:1fr}.founder img{max-width:240px}.top .btn{display:none}}'''

def funnel_page(slug):
    F = FUNNELS[slug]; path = slug + '/'; pre = '../'; canon = SITE + '/' + path
    cta = lambda cls='btn': f'<a class="{cls} mt" href="#" data-subj="{F["subj"]}">{E(F["cta"])} <span>&rarr;</span></a>'
    h1 = ''.join(f'<span class="l">{t}</span>' for t in F['h1'].split('|'))
    ld = [ORG_LD,
          {"@context":"https://schema.org","@type":"Service","name":F['eyebrow'].capitalize(),"serviceType":F['eyebrow'],"description":F['desc'],"url":canon,"provider":{"@id":SITE+"/#organization"},"areaServed":{"@type":"Country","name":"United States"}},
          {"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":q,"acceptedAnswer":{"@type":"Answer","text":a}} for q,a in F['faq']]}]
    lds = ''.join(f'<script type="application/ld+json">{json.dumps(x)}</script>' for x in ld)
    stats = ''.join(f'<div><b>{E(n)}</b><span>{E(l)}</span></div>' for n,l in F['stats'])
    why = ''.join(f'<div class="card"><h3>{E(a)}</h3><p>{E(b)}</p></div>' for a,b in F['why'])
    polls = ''.join(f'<li>{E(p)}</li>' for p in F['polls'])
    steps = ''.join(f'<div class="card"><span class="n">0{i+1}</span><h3>{E(a)}</h3><p>{E(b)}</p></div>' for i,(a,b) in enumerate(F['steps']))
    call = [('An honest read on your ads','We look at what you are running now and what is and is not working.'),('Your first 10 street polls','The questions we would take to the street to beat your current creative.'),('The three-month plan','How filming, testing and scaling winners works for you.')]
    calls = ''.join(f'<div class="card"><span class="n">0{i+1}</span><h3>{E(a)}</h3><p>{E(b)}</p></div>' for i,(a,b) in enumerate(call))
    faq = ''.join(f'<details><summary>{E(q)}</summary><p>{E(a)}</p></details>' for q,a in F['faq'])
    yes = ''.join(f'<li>{E(x)}</li>' for x in F['fit_yes']); no = ''.join(f'<li>{E(x)}</li>' for x in F['fit_no'])
    doc = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>{E(F["title"])}</title><meta name="description" content="{E(F["desc"])}"><meta name="keywords" content="{E(F["kw"])}"><link rel="canonical" href="{canon}">
<meta property="og:type" content="website"><meta property="og:site_name" content="Leo Operations"><meta property="og:title" content="{E(F["title"])}"><meta property="og:description" content="{E(F["desc"])}"><meta property="og:url" content="{canon}"><meta property="og:image" content="{SITE}/assets/img/v2-media.jpg"><meta name="twitter:card" content="summary_large_image">
<link rel="icon" href="/favicon.ico" sizes="48x48"><link rel="apple-touch-icon" href="{pre}assets/brand/apple-touch-icon.png">
<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter+Tight:wght@400;600;700&family=Unbounded:wght@500;600&display=swap" rel="stylesheet">
<style>{FUNNEL_CSS}</style>{lds}</head><body>
<header class="top"><span class="brand"><img src="{pre}assets/brand/shield.png" alt="" width="36" height="36"><b>LEO OPERATIONS</b></span>{cta("btn sm")}</header>
<main>
<section class="hero"><video autoplay muted loop playsinline preload="auto" poster="{pre}assets/img/v2-media.jpg"><source src="{pre}assets/img/v2-media-hd.mp4" type="video/mp4"></video><div class="sh"></div>
<div class="wrap"><span class="eb">{E(F["eyebrow"])}</span><h1 style="margin-top:18px">{h1}</h1><p class="sub">{E(F["sub"])}</p>{cta()}<span class="note">30-minute strategy call &middot; 3-month minimum</span></div></section>
<div class="wrap"><div class="stats">{stats}</div></div>
<section><div class="wrap"><span class="eb">Why it works</span><h2>Real people <span class="grad">stop the scroll.</span></h2><div class="cards">{why}</div></div></section>
<section style="padding-top:0"><div class="wrap"><span class="eb">The format</span><h2>Questions we take <span class="grad">to the street.</span></h2><p class="lead">A few examples. On the call we write the first 10 for you.</p><ul class="polls">{polls}</ul></div></section>
<section style="padding-top:0"><div class="wrap"><span class="eb">The call</span><h2>Your first 10 polls, <span class="grad">mapped on the call.</span></h2><p class="lead">30 minutes, one on one with a strategist. You leave with:</p><div class="cards">{calls}</div><div style="margin-top:30px">{cta()}</div></div></section>
<section style="padding-top:0"><div class="wrap"><span class="eb">Fit check</span><h2>Who this is <span class="grad">built for.</span></h2><div class="fit"><div class="card y"><h3>A good fit if</h3><ul>{yes}</ul></div><div class="card x"><h3>Not a fit if</h3><ul>{no}</ul></div></div></div></section>
<section style="padding-top:0"><div class="wrap"><span class="eb">How it works</span><h2>From street <span class="grad">to scale.</span></h2><div class="cards">{steps}</div></div></section>
<section style="padding-top:0"><div class="wrap founder"><img src="{pre}assets/team/rodriquez-wright-ii.jpg" alt="Rodriquez Wright II, founder of Leo Operations" loading="lazy"><div><span class="eb">Meet the founder</span><h2>Built by <span class="grad">Rodriquez Wright II.</span></h2><p class="lead">{E(F["founder"])}</p></div></div></section>
<section style="padding-top:0"><div class="wrap"><span class="eb">FAQ</span><h2>Before you <span class="grad">book.</span></h2>{faq}</div></section>
<section class="final"><div class="wrap"><span class="eb">Next step</span><h2>Map your <span class="grad">first 10 polls.</span></h2><p class="lead">One email starts it. We reply within one business day to set up your 30-minute call.</p>{cta()}<span class="note">Every program starts with a three-month minimum.</span></div></section>
</main>
<footer><span>&copy; 2026 Leo Operations, LLC. Nashville, Tennessee.</span><span><a href="{pre}privacy-policy/">Privacy Policy</a></span></footer>
<script>document.querySelectorAll('[data-subj]').forEach(function(a){{a.href='mailto:'+['rod','leooperations.com'].join('@')+'?subject='+a.dataset.subj}})</script>
</body></html>'''
    os.makedirs(os.path.join(OUT, slug), exist_ok=True)
    open(os.path.join(OUT, slug, 'index.html'), 'w').write(doc)
    PAGES.append(path)
